queries = {"Sales_raw": [], "Customers": [], "Sales": ["Sales_raw"], "Report": ["Sales", "Customers"]}


def refresh_order(depends_on):
    done, order = set(), []
    remaining = dict(depends_on)
    while remaining:
        ready = sorted(q for q, deps in remaining.items() if all(d in done for d in deps))
        if not ready:
            raise ValueError("circular reference")
        for q in ready:
            order.append(q)
            done.add(q)
            del remaining[q]
    return order


print(refresh_order(queries))
